    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    if any(c.isalpha() for c in s):
        chars = []
        for c in s:
            if c.isupper():
                chars.append(c.lower())
            elif c.islower():
                chars.append(c.upper())
            else:
                chars.append(c)
        return ''.join(chars)
    return s[::-1]
